/**
 * Every math instruction is read aloud: first graders cannot read the questions yet. One fixed
 * sentence per kind of question, generated by scripts/generate-math-audio.ts.
 */
import { isHan, readingVariants } from "../lesson/reading-variants";
import type { CountIcon } from "./math-round";
import geminiClips from "./math-audio-gemini.json";

const numerals = ["零", "一", "兩", "三", "四", "五", "六", "七", "八", "九", "十"];
const numeralReadings = "ㄌㄧㄥˊ ㄧ ㄌㄧㄤˇ ㄙㄢ ㄙˋ ㄨˇ ㄌㄧㄡˋ ㄑㄧ ㄅㄚ ㄐㄧㄡˇ ㄕˊ".split(" ");
/** In a sum, 2 is 二, not 兩: 二加三. */
const sumNumerals = ["零", "一", "二", ...numerals.slice(3)];
const sumReadings = ["ㄌㄧㄥˊ", "ㄧ", "ㄦˋ", ...numeralReadings.slice(3)];
export const chineseNumber = (value: number) => numerals[value] ?? String(value);

const range = (from: number, to: number) =>
  Array.from({ length: to - from + 1 }, (_, index) => from + index);
/**
 * Every sum 第七課 can ask: 合起來是多少 has up to 5 on each side, 加加看 sums are 3 to 10, and
 * 0的加法 adds 0 to 1–9 either way round.
 */
const joinPairs = range(1, 5).flatMap((a) => range(1, 5).map((b) => [a, b] as const));
const addPairs = [
  ...range(1, 9).flatMap((a) =>
    range(1, 9)
      .filter((b) => a + b >= 3 && a + b <= 10)
      .map((b) => [a, b] as const),
  ),
  ...range(1, 9).flatMap((value) => [[value, 0] as const, [0, value] as const]),
];
/** 第五課's flat shapes, with their readings, for 找圖形 and 做造型. */
const flatShapeNames: Record<string, [string, string]> = {
  square: ["正方形", "ㄓㄥˋ ㄈㄤ ㄒㄧㄥˊ"],
  rect: ["長方形", "ㄔㄤˊ ㄈㄤ ㄒㄧㄥˊ"],
  triangle: ["三角形", "ㄙㄢ ㄐㄧㄠˇ ㄒㄧㄥˊ"],
  circle: ["圓形", "ㄩㄢˊ ㄒㄧㄥˊ"],
};
/** 第三課 排在第幾個: rows of six or seven, never asking for the first or the last. */
const positionPlaces = range(2, 6);
/** 第三課 第幾個和幾個: 「點三個」 and 「點第三個」 in a row of seven. */
const groupCounts = range(2, 5);
/**
 * 第四課: 分一分 splits 3 to 10 any way; 合一合 has up to 5 on each side, or makes 10; 分分看 is
 * 10的分與合.
 */
const splitPairs = addPairs.filter(([a, b]) => a > 0 && b > 0);
const combinePairs = [
  ...joinPairs.filter(([a, b]) => a + b >= 3),
  ...range(1, 9)
    .filter((a) => a !== 5)
    .map((a) => [a, 10 - a] as const),
];
const waysTotals = [10];
/**
 * 認識 0 names what is not there, with its measure word, so a child counts the things and not
 * the empty place: 「這裡有幾隻小鳥？」. Keyed by the picture a round would have counted.
 */
const zeroThings: Record<CountIcon, [string, string]> = {
  fish: ["條魚", "ㄊㄧㄠˊ ㄩˊ"],
  bird: ["隻小鳥", "ㄓ ㄒㄧㄠˇ ㄋㄧㄠˇ"],
  tulip: ["朵花", "ㄉㄨㄛˇ ㄏㄨㄚ"],
  star: ["顆星星", "ㄎㄜ ㄒㄧㄥ ㄒㄧㄥ"],
  heart: ["顆愛心", "ㄎㄜ ㄞˋ ㄒㄧㄣ"],
  car: ["輛汽車", "ㄌㄧㄤˋ ㄑㄧˋ ㄔㄜ"],
  iceCream: ["支冰淇淋", "ㄓ ㄅㄧㄥ ㄑㄧˊ ㄌㄧㄣˊ"],
  carrot: ["根紅蘿蔔", "ㄍㄣ ㄏㄨㄥˊ ㄌㄨㄛˊ ˙ㄅㄛ"],
  balloon: ["顆氣球", "ㄎㄜ ㄑㄧˋ ㄑㄧㄡˊ"],
  butterfly: ["隻蝴蝶", "ㄓ ㄏㄨˊ ㄉㄧㄝˊ"],
  acorn: ["顆橡實", "ㄎㄜ ㄒㄧㄤˋ ㄕˊ"],
  leaf: ["片葉子", "ㄆㄧㄢˋ ㄧㄝˋ ˙ㄗ"],
};

